import {CopilotErrorIcon, CopilotWarningIcon} from '@primer/octicons-react'
import {Flash} from '@primer/react'

import styles from './CopilotSummaryErrorBanner.module.css'

export interface CopilotSummaryErrorBannerProps {
  bannerMessage: string
  isServerError: boolean
}

export function CopilotSummaryErrorBanner({bannerMessage, isServerError}: CopilotSummaryErrorBannerProps) {
  return (
    <Flash variant="danger" className={styles.flash} data-testid="copilot-summary-error-banner">
      <div className={styles.contentRow}>
        <div className={styles.iconContainer} data-testid="copilot-summary-error-banner-icon">
          {isServerError ? <CopilotErrorIcon size={12} /> : <CopilotWarningIcon size={12} />}
        </div>
        <span className={styles.messageText} data-testid="copilot-summary-error-banner-message">
          {bannerMessage}
        </span>
      </div>
    </Flash>
  )
}
